import re
from typing import Any, Dict, List, Tuple, Union

# ----------------------------------------------------------------------
# Tokenizer
# ----------------------------------------------------------------------
Token = Tuple[str, str]  # (type, value)

TOKEN_SPEC = [
    ("NUMBER",   r"-?\d+"),
    ("CELL",     r"[A-Z][1-9]\d?"),          # A1..Z99
    ("IDENT",    r"[A-Z]+"),                # function names
    ("EQ",       r"="),
    ("NE",       r"<>"),
    ("LE",       r"<="),
    ("GE",       r">="),
    ("LT",       r"<"),
    ("GT",       r">"),
    ("PLUS",     r"\+"),
    ("MINUS",    r"-"),
    ("TIMES",    r"\*"),
    ("DIV",      r"/"),
    ("LPAREN",   r"\("),
    ("RPAREN",   r"\)"),
    ("COMMA",    r","),
    ("COLON",    r":"),
    ("SKIP",     r"[ \t\r\n]+"),
]

TOK_REGEX = re.compile("|".join(f"(?P<{name}>{pattern})" for name, pattern in TOKEN_SPEC))


def tokenize(s: str) -> List[Token]:
    tokens: List[Token] = []
    for m in TOK_REGEX.finditer(s):
        typ = m.lastgroup
        if typ == "SKIP":
            continue
        val = m.group(typ)
        tokens.append((typ, val))
    tokens.append(("EOF", ""))
    return tokens


# ----------------------------------------------------------------------
# AST nodes
# ----------------------------------------------------------------------
class Node:
    pass


class Number(Node):
    def __init__(self, value: int):
        self.value = value


class CellRef(Node):
    def __init__(self, name: str):
        self.name = name


class UnaryMinus(Node):
    def __init__(self, expr: Node):
        self.expr = expr


class BinOp(Node):
    def __init__(self, left: Node, op: str, right: Node):
        self.left = left
        self.op = op
        self.right = right


class FuncCall(Node):
    def __init__(self, name: str, args: List[Node]):
        self.name = name
        self.args = args


class Range(Node):
    def __init__(self, start: str, end: str):
        self.start = start
        self.end = end


# ----------------------------------------------------------------------
# Parser (recursive descent)
# ----------------------------------------------------------------------
class Parser:
    def __init__(self, tokens: List[Token]):
        self.tokens = tokens
        self.pos = 0

    def peek(self) -> Token:
        return self.tokens[self.pos]

    def advance(self) -> Token:
        cur = self.tokens[self.pos]
        self.pos += 1
        return cur

    def expect(self, typ: str) -> Token:
        tok = self.advance()
        if tok[0] != typ:
            raise SyntaxError(f"Expected {typ}, got {tok}")
        return tok

    # entry
    def parse(self) -> Node:
        node = self.expr()
        if self.peek()[0] != "EOF":
            raise SyntaxError("Extra input")
        return node

    # expr -> additive
    def expr(self) -> Node:
        return self.additive()

    # additive -> mult ( (PLUS|MINUS) mult )*
    def additive(self) -> Node:
        node = self.mult()
        while self.peek()[0] in ("PLUS", "MINUS"):
            op = self.advance()[1]
            right = self.mult()
            node = BinOp(node, op, right)
        return node

    # mult -> unary ( (TIMES|DIV) unary )*
    def mult(self) -> Node:
        node = self.unary()
        while self.peek()[0] in ("TIMES", "DIV"):
            op = self.advance()[1]
            right = self.unary()
            node = BinOp(node, op, right)
        return node

    # unary -> MINUS unary | primary
    def unary(self) -> Node:
        if self.peek()[0] == "MINUS":
            self.advance()
            return UnaryMinus(self.unary())
        return self.primary()

    # primary -> NUMBER | CELL | '(' expr ')' | func_call
    def primary(self) -> Node:
        tok_type, tok_val = self.peek()
        if tok_type == "NUMBER":
            self.advance()
            return Number(int(tok_val))
        if tok_type == "CELL":
            self.advance()
            return CellRef(tok_val)
        if tok_type == "LPAREN":
            self.advance()
            node = self.expr()
            self.expect("RPAREN")
            return node
        if tok_type == "IDENT":
            return self.func_call()
        raise SyntaxError(f"Unexpected token {tok_type}")

    # func_call -> IDENT '(' arglist ')'
    def func_call(self) -> Node:
        name = self.expect("IDENT")[1]
        self.expect("LPAREN")
        if name == "IF":
            # special parsing for IF(left OP right, then, else)
            left = self.expr()
            op_tok = self.advance()
            if op_tok[0] not in ("EQ", "NE", "LT", "LE", "GT", "GE"):
                raise SyntaxError("Invalid IF comparator")
            op = op_tok[1]
            right = self.expr()
            self.expect("COMMA")
            then_branch = self.expr()
            self.expect("COMMA")
            else_branch = self.expr()
            self.expect("RPAREN")
            # we encode IF as a FuncCall with a tuple storing comparator
            return FuncCall("IF", [left, op, right, then_branch, else_branch])
        else:
            args = self.arglist()
            self.expect("RPAREN")
            return FuncCall(name, args)

    # arglist -> (range_or_expr (',' range_or_expr)*)?
    def arglist(self) -> List[Node]:
        args: List[Node] = []
        if self.peek()[0] == "RPAREN":
            return args
        while True:
            args.append(self.range_or_expr())
            if self.peek()[0] == "COMMA":
                self.advance()
                continue
            break
        return args

    # range_or_expr -> CELL ':' CELL | expr
    def range_or_expr(self) -> Node:
        # lookahead for CELL COLON CELL
        if self.peek()[0] == "CELL":
            # save position
            saved_pos = self.pos
            start_cell = self.advance()[1]
            if self.peek()[0] == "COLON":
                self.advance()  # consume colon
                if self.peek()[0] == "CELL":
                    end_cell = self.advance()[1]
                    return Range(start_cell, end_cell)
                else:
                    raise SyntaxError("Expected cell after ':'")
            else:
                # not a range, revert
                self.pos = saved_pos
        # otherwise parse as expr
        return self.expr()


# ----------------------------------------------------------------------
# Evaluation
# ----------------------------------------------------------------------
CellValue = Union[int, str]  # int or "#DIV/0!" or "#CYCLE!"

DIV0 = "#DIV/0!"
CYCLE = "#CYCLE!"


def trunc_div(a: int, b: int) -> int:
    # truncate toward zero
    return int(a / b)


def cell_to_coords(name: str) -> Tuple[int, int]:
    col = ord(name[0]) - ord("A")
    row = int(name[1:]) - 1  # zero‑based
    return row, col


def generate_range(start: str, end: str) -> List[str]:
    r1, c1 = cell_to_coords(start)
    r2, c2 = cell_to_coords(end)
    r_start, r_end = sorted((r1, r2))
    c_start, c_end = sorted((c1, c2))
    cells = []
    for r in range(r_start, r_end + 1):
        for c in range(c_start, c_end + 1):
            cells.append(f"{chr(ord('A') + c)}{r + 1}")
    return cells


class Evaluator:
    def __init__(self, cells: Dict[str, str]):
        self.cells = cells
        self.cache: Dict[str, CellValue] = {}
        self.in_progress: Dict[str, bool] = {}

    def evaluate_cell(self, name: str) -> CellValue:
        if name in self.cache:
            return self.cache[name]
        if self.in_progress.get(name, False):
            # cycle detected
            self.cache[name] = CYCLE
            return CYCLE
        self.in_progress[name] = True
        content = self.cells.get(name, "0")
        if not content.startswith("="):
            # literal integer (may be negative)
            try:
                val = int(content)
            except ValueError:
                val = 0  # shouldn't happen per spec
            result: CellValue = val
        else:
            expr_str = content[1:]  # strip leading '='
            try:
                node = Parser(tokenize(expr_str)).parse()
                result = self.eval_node(node)
            except Exception:
                # parsing errors shouldn't happen per spec
                result = CYCLE
        self.cache[name] = result
        self.in_progress[name] = False
        return result

    # ------------------------------------------------------------------
    # Node evaluation helpers
    # ------------------------------------------------------------------
    def eval_node(self, node: Node) -> CellValue:
        if isinstance(node, Number):
            return node.value
        if isinstance(node, CellRef):
            # missing cells are treated as 0
            if node.name not in self.cells:
                return 0
            return self.evaluate_cell(node.name)
        if isinstance(node, UnaryMinus):
            val = self.eval_node(node.expr)
            if isinstance(val, str):
                return val
            return -val
        if isinstance(node, BinOp):
            left = self.eval_node(node.left)
            if isinstance(left, str):
                return left
            right = self.eval_node(node.right)
            if isinstance(right, str):
                return right
            if node.op == "+":
                return left + right
            if node.op == "-":
                return left - right
            if node.op == "*":
                return left * right
            if node.op == "/":
                if right == 0:
                    return DIV0
                return trunc_div(left, right)
            raise RuntimeError(f"Unknown operator {node.op}")
        if isinstance(node, FuncCall):
            if node.name == "IF":
                # args: left, op, right, then, else
                left_val = self.eval_node(node.args[0])
                if isinstance(left_val, str):
                    return left_val
                right_val = self.eval_node(node.args[2])
                if isinstance(right_val, str):
                    return right_val
                op = node.args[1]  # comparator string
                cond = self.compare(left_val, op, right_val)
                # cond is bool
                branch = node.args[3] if cond else node.args[4]
                return self.eval_node(branch)
            # other functions: SUM, MIN, MAX
            args_vals: List[int] = []
            for arg in node.args:
                if isinstance(arg, Range):
                    cells = generate_range(arg.start, arg.end)
                    for cell_name in cells:
                        if cell_name not in self.cells:
                            continue  # skip missing cells
                        val = self.evaluate_cell(cell_name)
                        if isinstance(val, str):
                            return val  # first error propagates
                        args_vals.append(val)
                else:
                    v = self.eval_node(arg)
                    if isinstance(v, str):
                        return v
                    args_vals.append(v)
            if node.name == "SUM":
                return sum(args_vals)
            if node.name == "MIN":
                return min(args_vals) if args_vals else 0
            if node.name == "MAX":
                return max(args_vals) if args_vals else 0
            raise RuntimeError(f"Unknown function {node.name}")
        if isinstance(node, Range):
            # a range alone should not appear outside function args; treat as error
            raise RuntimeError("Range used as expression")
        raise RuntimeError("Unsupported node type")

    def compare(self, left: int, op: str, right: int) -> bool:
        if op == "=":
            return left == right
        if op == "<>":
            return left != right
        if op == "<":
            return left < right
        if op == "<=":
            return left <= right
        if op == ">":
            return left > right
        if op == ">=":
            return left >= right
        raise RuntimeError(f"Invalid comparator {op}")


# ----------------------------------------------------------------------
# Public API
# ----------------------------------------------------------------------
def sheet(cells: dict[str, str]) -> dict[str, int | str]:
    """
    Evaluate the spreadsheet described by ``cells``.
    Returns a dictionary mapping each cell name to its integer value or an error string.
    """
    evaluator = Evaluator(cells)
    result: dict[str, int | str] = {}
    for name in cells:
        result[name] = evaluator.evaluate_cell(name)
    return result
